fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and choose 'Credentials'; it opens on the Overview section. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) credentials-overview — confirm the Overview renders its bespoke computed dashboard: a circular health-score ring showing a numeric score with a health label (Healthy / Needs Attention / Critical), a row of KPI cards (Total Credentials, Active, Types, Expiring Soon, Expired), and the 'Credentials by Category' donut panel plus a 'Top Credential Types' panel, each with data or a valid empty state; (2) section-click-through — click the 'Total Credentials' KPI card (or a listed type in the 'Top Credential Types' panel), which should navigate away from the Overview to the Credentials (or Types) section, and confirm that destination section renders its list (filtered or full). Keep going until both sections are done. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "credentials-overview",
      "instruction": "Credentials Overview computed dashboard",
      "visualCriteria": [
        "The Credentials Overview shows a circular health-score ring with a numeric score and a health label (Healthy/Needs Attention/Critical), a KPI card row (Total Credentials, Active, Types, Expiring Soon, Expired), and both a 'Credentials by Category' donut panel and a 'Top Credential Types' panel (each with content or a valid empty state)"
      ]
    },
    {
      "name": "section-click-through",
      "instruction": "click a KPI card / type to navigate to a section",
      "visualCriteria": [
        "Clicking a KPI card or a listed type navigates away from the Overview to the Credentials list or Types section, and that destination section renders its content (filtered or full)"
      ]
    }
  ]
}
